import{_ as d,o as a,c as e,a2 as r}from"./chunks/framework.CdvW4CUT.js";const m=JSON.parse('{"title":"规范总览","description":"","frontmatter":{"title":"规范总览"},"headers":[],"relativePath":"guide/index.md","filePath":"guide/index.md","lastUpdated":null}'),l={name:"guide/index.md"};function s(n,t,o,h,i,p){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="规范总览" tabindex="-1">规范总览 <a class="header-anchor" href="#规范总览" aria-label="Permalink to &quot;规范总览&quot;">​</a></h1><div class="spec-meta"><span>版本：<b>v0.1</b></span><span>更新日期：<b>待填写</b></span><span>维护人：<b>待填写</b></span><span>适用端：<b>Web 端（PC 浏览器）</b></span></div><p>本文件是规范的<strong>唯一源文件</strong>。Trae 规则从<a href="/resources/trae-rules.html">第 2–8 节</a>派生，前端 Token 与本文件同源，<strong>不要单独维护两份数值</strong>。</p><h2 id="版本信息" tabindex="-1">版本信息 <a class="header-anchor" href="#版本信息" aria-label="Permalink to &quot;版本信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>内容</th></tr></thead><tbody><tr><td>当前版本</td><td>v0.1</td></tr><tr><td>更新日期</td><td>待填写</td></tr><tr><td>维护人</td><td>待填写</td></tr><tr><td>适用端</td><td>Web 端（PC 浏览器）</td></tr><tr><td>适用角色</td><td>UI 设计师、前端开发、测试、产品经理</td></tr><tr><td>源文件</td><td><code>公司产品 UI 设计规范.md</code></td></tr></tbody></table><h2 id="强制等级图例" tabindex="-1">强制等级图例 <a class="header-anchor" href="#强制等级图例" aria-label="Permalink to &quot;强制等级图例&quot;">​</a></h2><p>规范中每条规则都带强制等级，用于判断「违反是否算缺陷」。</p><table tabindex="0"><thead><tr><th>标识</th><th>等级</th><th>含义</th><th>处理方式</th></tr></thead><tbody><tr><td><span class="level level-must">🔴 强制</span></td><td>Must</td><td>违反即缺陷</td><td>代码评审与走查必须拦截，不允许偏离</td></tr><tr><td><span class="level level-recommend">🟡 推荐</span></td><td>Should</td><td>可偏离</td><td>偏离需在评审中说明理由</td></tr><tr><td><span class="level level-optional">⚪ 可选</span></td><td>May</td><td>由项目自定</td><td>无约束，同一项目内部保持一致即可</td></tr></tbody></table><h2 id="适用范围" tabindex="-1">适用范围 <a class="header-anchor" href="#适用范围" aria-label="Permalink to &quot;适用范围&quot;">​</a></h2><p><strong>适用端</strong>：Web 端（PC 浏览器）。以下内容不在本规范范围内：</p><ul><li>移动端 / 小程序 / 原生客户端界面；</li><li>市场宣传物料、插画与动效设计；</li><li>具体业务的信息架构与文案规范。</li></ul><p><strong>适用角色</strong>与各自的使用方式：</p><table tabindex="0"><thead><tr><th>角色</th><th>关注章节</th><th>用法</th></tr></thead><tbody><tr><td>UI 设计师</td><td>2 / 3 / 4 / 5 / 6</td><td>出图时直接引用 Token 数值，不自定义色值</td></tr><tr><td>前端开发</td><td>2 / 4 / 5 / 6 / 7</td><td>将 Token 落到 CSS 变量，组件样式只引用变量</td></tr><tr><td>测试</td><td>6 / 7 / 8</td><td>按<a href="/guide/delivery.html">走查清单</a>逐项验收</td></tr><tr><td>产品经理</td><td>1 / 6</td><td>验收时判断一致性、状态完整性</td></tr></tbody></table><h2 id="规范结构" tabindex="-1">规范结构 <a class="header-anchor" href="#规范结构" aria-label="Permalink to &quot;规范结构&quot;">​</a></h2><p>规范共 9 节，本站在章节编号上与源文件保持一致，便于对照：</p><table tabindex="0"><thead><tr><th>节</th><th>标题</th><th>本站页面</th><th>等级</th></tr></thead><tbody><tr><td>0</td><td>适用范围</td><td>本节</td><td>—</td></tr><tr><td>1</td><td>设计原则</td><td><a href="/guide/principles.html">设计原则</a></td><td><span class="level level-must">强制</span></td></tr><tr><td>2</td><td>色彩规范</td><td><a href="/foundation/color.html">色彩规范</a></td><td><span class="level level-must">强制</span></td></tr><tr><td>3</td><td>字体与排版</td><td><a href="/foundation/typography.html">字体与排版</a></td><td><span class="level level-must">强制</span></td></tr><tr><td>4</td><td>间距与栅格</td><td><a href="/foundation/spacing.html">间距与栅格</a></td><td><span class="level level-must">强制</span></td></tr><tr><td>5</td><td>圆角、阴影与层级</td><td><a href="/foundation/radius-shadow.html">圆角与阴影</a></td><td><span class="level level-recommend">推荐</span></td></tr><tr><td>6</td><td>组件规范</td><td><a href="/components/button.html">按钮</a> · <a href="/components/form.html">表单</a> · <a href="/components/table.html">表格</a> · <a href="/components/modal.html">弹窗</a></td><td><span class="level level-must">强制</span></td></tr><tr><td>7</td><td>交互与可访问性</td><td><a href="/guide/accessibility.html">交互与可访问性</a></td><td><span class="level level-recommend">推荐</span></td></tr><tr><td>8</td><td>交付与验收</td><td><a href="/guide/delivery.html">交付与验收</a></td><td>—</td></tr><tr><td>9</td><td>Trae 规则文件</td><td><a href="/resources/trae-rules.html">Trae 规则文件</a>（派生）</td><td>—</td></tr></tbody></table><h2 id="维护约定" tabindex="-1">维护约定 <a class="header-anchor" href="#维护约定" aria-label="Permalink to &quot;维护约定&quot;">​</a></h2><ul class="rules"><li class="must">修改任何数值（色值、字号、间距、圆角、阴影）只允许改源文件，本站与 Trae 规则同步更新，禁止只改其中一处。</li><li class="must">新增 Token 必须同时给出：Token 名、用途、具体值三项，缺一不可。</li><li class="recommend">新增规则需标注强制等级；未标注等级视作推荐级。</li><li class="recommend">版本号按语义化递增：数值调整升次版本号，规则增删升主版本号。</li></ul>',18)])])}const u=d(l,[["render",s]]);export{m as __pageData,u as default};
